con:config.script:
// -------------------------
// drive to shipTo
// -------------------------
log.info("-- drive from Shippingpoint to ShippingTo --")

// init behavior
Number num_steps = 4
String name_iterative_step = "Run geoPos"
String name_final_step = "waitingOnShipTo" 
String target_suite_name = "LOGON-initiated-HelperSuite"

// init context vars
def runner = context.getTestRunner()
def properties = runner.testCase.getTestStepByName("Properties")
def counter = properties.getProperty("_counter")

// target step
def target_suite = runner.testCase.testSuite.project.getTestSuiteByName(target_suite_name)
def target_case = target_suite.getTestCaseByName("geoPosition_simple")
def target_step = target_case.getTestStepByName("Properties")

target_step.setPropertyValue("curr_sessionID", properties.getPropertyValue("curr_sessionID"))

//Number start_x = 47.4
//Number start_y = 8.53
Number start_x = Float.parseFloat(properties.getPropertyValue("shippingpointCoordLat"))
Number start_y = Float.parseFloat(properties.getPropertyValue("shippingpointCoordLon"))
Number target_x = Float.parseFloat(properties.getPropertyValue("shipToCoordLat"))
Number target_y = Float.parseFloat(properties.getPropertyValue("shipToCoordLon"))
Number step_x = (start_x - target_x).abs()/num_steps
Number step_y = (start_y - target_y).abs()/num_steps
Number dir_x = (start_x > target_x) ? -1 : 1
Number dir_y = (start_y > target_y) ? -1 : 1

c_int = Integer.parseInt(counter.getValue())
if (c_int < num_steps){
	inc(counter);
	// update message property
	cur_x = start_x + (c_int + 1)*step_x * dir_x
	cur_y = start_y + (c_int + 1)*step_y * dir_y 
	target_step.setPropertyValue("geoX_0", cur_x.toString())
	target_step.setPropertyValue("geoY_0", cur_y.toString())
	log.info("cur geoPos: " + cur_x + ", " + cur_y + " couter = " + c_int)
	// run 
	runner.gotoStepByName(name_iterative_step)
}else{
	// Perpare for enterShippingPoint
	runner.gotoStepByName(name_final_step)
}
// increment counter
public inc(prop){
	def c = Integer.parseInt(prop.getValue())
	c = c + 1
	prop.setValue(c.toString())

}

